				return "", err
			}
			resolved = resolved[:len(resolved)-1]
			continue
		}
		candidate := filepath.Join(append(slices.Clone(resolved), component)...)
		info, err := root.Lstat(candidate)
		if err != nil {
			if errors.Is(err, fs.ErrNotExist) {
				resolved = append(resolved, component)
				continue
			}
