	s = strings.TrimSuffix(strings.Trim(strings.TrimSpace(s), "/"), ".git")
	var parts []string
	for _, p := range strings.Split(s, "/") {
		if p = cleanComponent(strings.ToLower(p)); p != "" {
			parts = append(parts, p)
		}
	}
	return parts
}
