func TestDefaultRefreshAgentHonorsNoEgressMode(t *testing.T) {
	t.Setenv("ENTIRE_BRAIN_NO_EGRESS", "1")
	runner := &fakeCommandRunner{responses: map[string]fakeCommandResponse{
