		t.Fatalf("create session dir: %v", err)
	}
	if err := os.WriteFile(sessionPath, []byte("session\n"), 0o600); err != nil {
		t.Fatalf("write session: %v", err)
	}
	files, err := collectHistorySessionDigests(context.Background(), brainDir, nil)
	if err != nil {
