		Provenance: []factAnchor{{SessionID: "session-C"}}, CreatedAt: f.now, UpdatedAt: f.now,
	}
	f.writeFacts(t, "main", []factRecord{local})

	out, err := execute(t, NewRootCommand(f.opts), "facts", "sync", "--facts-backend", "http", "--member", "member-C")

