				needsRebuild = !indexCurrent || !verifyAvailable || !verify.Clean || !receiptsCurrent || !ok || receipt.InputDigest != digest
			}
			if needsRebuild && !dryRun {
				if err := rebuildMemoryProjection(brainDir, now); err != nil {
					return fail(err)
				}
