			order = append(order, t.QueryType)
		}
		buckets[t.QueryType] = append(buckets[t.QueryType], t)
	}
	sort.Strings(order)
	var out []evalTask
	for len(out) < n {
		progressed := false
		for _, qt := range order {
			if len(buckets[qt]) == 0 {
				continue
			}
			out = append(out, buckets[qt][0])
			buckets[qt] = buckets[qt][1:]
			progressed = true
			if len(out) >= n {
				break
			}
		}
