	cmd.Flags().BoolVar(&jsonOut, "json", false, "Emit machine-readable JSON")
	cmd.Flags().StringVar(&sessionRef, "session-ref", "", "Repair the monolithic projection only when this canonical session is stale or missing")
	return cmd
}

