func newFactsMapCommand(opts Options) *cobra.Command {
	var (
		branch  string
		path    string
		depth   int
		jsonOut bool
	)
	cmd := &cobra.Command{
		Use:   "map",
		Short: "Render the synthesized fact outline (summaries + structure) with progressive disclosure",
		Args:  cobra.NoArgs,
		RunE: func(cmd *cobra.Command, args []string) error {
			_, brainDir, resolvedBranch, err := resolveFactsTarget(cmd.Context(), opts, agentSurfaceTarget(opts, nil), branch)
			if err != nil {
				return err
			}
			// Always rebuild the structure from the live facts (it is deterministic
			// and never stale), then overlay stored summaries only where the node's
			// fingerprint still matches — so a summary for a changed subtree is
			// hidden rather than shown stale, and no `facts outline` run is required
			// to see the map.
			facts, err := loadFacts(brainDir, resolvedBranch)
			if err != nil {
				return err
			}
			outline := buildFactOutlineTree(resolvedBranch, facts, opts.Now().UTC())
			if stored, storedErr := loadFactOutline(brainDir, resolvedBranch); storedErr == nil {
				for key, n := range outline.Nodes {
					if s, ok := stored.Nodes[key]; ok && s.Fingerprint == n.Fingerprint && s.Summary != "" {
						n.Summary = s.Summary
						outline.Nodes[key] = n
					}
				}
			}
			node := path
			if _, ok := outline.Nodes[node]; !ok {
				return fmt.Errorf("no outline node %q on %s", path, resolvedBranch)
			}
			// The outline counts what loadFacts produced. When the manifest
			// declares more than that, "root (4 facts)" is a count of survivors
			// rendered as if it were the corpus. Qualify it before rendering,
			// and exit nonzero so a caller cannot read the map as complete.
			integrityErr := reportFactStoreIntegrity(cmd, brainDir, jsonOut)
			if jsonOut {
				if err := writeJSON(cmd, outline); err != nil {
					return err
				}
				return integrityErr
			}
			var b strings.Builder
			renderFactOutline(&b, outline, node, depth)
			if b.Len() == 0 {
				fmt.Fprintf(cmd.OutOrStdout(), "no facts on %s\n", resolvedBranch)
				return integrityErr
			}
			fmt.Fprint(cmd.OutOrStdout(), b.String())
			return integrityErr
		},
	}
	cmd.Flags().StringVar(&branch, "branch", "", "Branch to map (default: current branch)")
	cmd.Flags().StringVar(&path, "path", "", "Drill into a node key (a directory tier, e.g. internal/cli)")
	cmd.Flags().IntVar(&depth, "depth", 0, "Levels to render below the node (0 = all)")
	cmd.Flags().BoolVar(&jsonOut, "json", false, "Emit the outline as JSON")
	return cmd
}

func runFactsGC(cmd *cobra.Command, opts Options, brainDir, branch string, force bool, retain time.Duration, jsonOut bool) error {
	facts, err := loadFacts(brainDir, branch)
	if err != nil {
		return err
	}
	now := opts.Now().UTC()
	taxonomy, err := loadFactTaxonomy(brainDir, now)
	if err != nil {
		return err
	}
	result := gcFacts(facts, taxonomy, now, retain)

	summary := map[string]any{
		"branch":    branch,
		"pruned":    len(result.Pruned),
		"orphans":   len(result.Orphans),
		"remaining": len(result.Kept),
		"applied":   force,
	}
	if force {
		if err := withBrainWriteLock(brainDir, func() error {
			facts, err := loadFacts(brainDir, branch)
			if err != nil {
				return err
			}
			taxonomy, err := loadFactTaxonomy(brainDir, now)
			if err != nil {
				return err
			}
			result = gcFacts(facts, taxonomy, now, retain)
			summary["pruned"] = len(result.Pruned)
			summary["orphans"] = len(result.Orphans)
			summary["remaining"] = len(result.Kept)
			if err := writeFacts(brainDir, branch, result.Kept); err != nil {
				return err
			}
			return updateFactSourceManifestLocked(brainDir, now)
		}); err != nil {
			return err
		}
	}
	if len(out.Children) == 0 {
		return nil
	}
	return out
}

// renderFactTree writes the outline. depth 1 prints categories only; depth 2
// adds the path leaves; depth >= 3 adds up to `leaves` sample facts per leaf
// with a "+N more" pointer so the rest is reachable via recall or a deeper
// drill, never silently hidden.
func renderFactTree(cmd *cobra.Command, root *factTreeNode, depth, leaves int) {
	for _, cat := range root.Children {
		fmt.Fprintf(cmd.OutOrStdout(), "%s (%d)\n", cat.Label, cat.Count)
		if depth < 2 {
			continue
		}
		for _, leaf := range cat.Children {
			fmt.Fprintf(cmd.OutOrStdout(), "  %s (%d)\n", leaf.Label, leaf.Count)
			if depth < 3 {
				continue
			}
			shown := leaf.Facts
			if len(shown) > leaves {
				shown = shown[:leaves]
			}
			for _, f := range shown {
				fmt.Fprintf(cmd.OutOrStdout(), "    - %s\n", truncateString(f.Text, 140))
			}
			if rest := leaf.Count - len(shown); rest > 0 {
				fmt.Fprintf(cmd.OutOrStdout(), "    (+%d more — drill with --path %s)\n", rest, leaf.Label)
			}
		}
	}
}

func newFactsTreeCommand(opts Options) *cobra.Command {
	var (
		branch     string
		path       string
		kind       string
		depth      int
		leaves     int
		includeAll bool
		scope      string
		jsonOut    bool
	)
	cmd := &cobra.Command{
		Use:   "tree",
		Short: "Show facts as a navigable hierarchy with progressive disclosure",
		Args:  cobra.NoArgs,
		RunE: func(cmd *cobra.Command, args []string) error {
			if err := validateScopeFlag(scope); err != nil {
				return err
			}
			if err := validateKindFlag(kind); err != nil {
				return err
			}
			_, brainDir, resolvedBranch, err := resolveFactsTarget(cmd.Context(), opts, agentSurfaceTarget(opts, nil), branch)
			if err != nil {
				return err
			}
			facts, err := loadFacts(brainDir, resolvedBranch)
			if err != nil {
				return err
			}
			facts = filterFactsByKind(filterFactsByScope(facts, scope), kind)
			tree := buildFactTree(facts, includeAll)
			if path != "" {
				if pruned := filterTreeByPath(tree, path); pruned != nil {
					tree = pruned
				} else {
					tree = &factTreeNode{Label: "facts"}
				}
			}
			// "N facts on main" is a count of what the store produced. When the
			// manifest declares more, that N is survivors, not the corpus — the
			// same lie `facts map` told. Qualify it, and exit nonzero.
			integrityErr := reportFactStoreIntegrity(cmd, brainDir, jsonOut)
			if jsonOut {
				if err := writeJSON(cmd, tree); err != nil {
					return err
				}
				return integrityErr
			}
			distinct := distinctFactCount(tree)
			if distinct == 0 {
				fmt.Fprintf(cmd.OutOrStdout(), "no facts on %s%s\n", resolvedBranch, pathSuffix(path))
				return integrityErr
			}
			fmt.Fprintf(cmd.OutOrStdout(), "%d facts on %s%s\n", distinct, resolvedBranch, pathSuffix(path))
			renderFactTree(cmd, tree, depth, leaves)
			return integrityErr
		},
	}
	cmd.Flags().StringVar(&branch, "branch", "", "Branch to outline (default: current branch)")
	cmd.Flags().StringVar(&path, "path", "", "Drill into a category or path prefix (e.g. constraints or preferences.coding)")
	cmd.Flags().IntVar(&depth, "depth", 3, "Outline depth: 1=categories, 2=+paths, 3=+sample facts")
	cmd.Flags().IntVar(&leaves, "leaves", 3, "Sample facts to show per path at depth 3")
	cmd.Flags().BoolVar(&includeAll, "all", false, "Include superseded and retracted facts")
	cmd.Flags().StringVar(&scope, "scope", "", "Restrict to 'local' (code/subsystem) or 'cross-cutting' (preferences/workflow) facts")
	cmd.Flags().StringVar(&kind, "kind", "", "Restrict to one kind: decision|invariant|gotcha|preference|convention")
	cmd.Flags().BoolVar(&jsonOut, "json", false, "Emit the tree as JSON")
	return cmd
}

func pathSuffix(path string) string {
	if strings.TrimSpace(path) == "" {
		return ""
	}
	return " under " + path
}

