package cli

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"time"
)

// facts_outline.go builds the Appendix-D "synthesized hierarchical outline": a
// living, locus-tiered map of the durable facts where each node carries a
// concise rollup summary of its subtree and leaves are atomic facts. The tree
// structure is deterministic (no agent) so `facts map` is useful immediately;
// the summaries are agent-generated and incremental — only nodes whose subtree
// fingerprint changed are re-summarized, so a refresh is cheap.

const factsOutlineFileName = "outline.json"

// factOutlineNode is one tier in the outline. Key is a slash-joined directory
// path ("" is the root); leaves are the facts homed directly at this tier and
// children are the immediate sub-tiers.
type factOutlineNode struct {
	Key         string         `json:"key"`
	Label       string         `json:"label"`
	Summary     string         `json:"summary,omitempty"`
	Fingerprint string         `json:"fingerprint"`
	Children    []string       `json:"children,omitempty"`
	LeafFactIDs []string       `json:"leaf_fact_ids,omitempty"`
	Counts      map[string]int `json:"counts,omitempty"`
}

// factOutline is the persisted artifact (facts/<branch>/outline.json). Nodes are
// keyed by their Key for O(1) incremental lookup; Root is always "".
type factOutline struct {
	GeneratedAt time.Time                  `json:"generated_at"`
	Branch      string                     `json:"branch"`
	Root        string                     `json:"root"`
	Nodes       map[string]factOutlineNode `json:"nodes"`
}

func factsOutlineRelPath(branch string) string {
	return filepath.ToSlash(filepath.Join(factsBranchRelDir(branch), factsOutlineFileName))
}

// parentKey returns the parent tier of a node key ("internal/cli" -> "internal"
// -> ""). The root ("") is its own parent and is handled by callers.
func parentKey(key string) string {
	if i := strings.LastIndexByte(key, '/'); i >= 0 {
		return key[:i]
	}
	return ""
}

// outlineLabel is the human display label for a node key: "root" for the root,
// otherwise the last path segment.
func outlineLabel(key string) string {
	if key == "" {
		return "root"
	}
	return filepath.Base(key)
}

// factHomeKey returns the tier a fact lives at: the directory of the deepest
// real source-file path named in its locus, or "" (root) for a cross-cutting
// fact or one with no file-path locus. Only genuine `dir/name.ext` paths tier a
// fact — slash-bearing prose tokens (`allow/deny`, `agent/model`) do not — so
// the outline mirrors the code layout rather than fragmenting into noise nodes.
func factHomeKey(f factRecord) string {
	if factScope(f.Paths) == factScopeCrossCutting {
		return ""
	}
	best := ""
	for _, tok := range factLocusOf(f) {
		if !looksLikeSourcePath(tok) {
			continue
		}
		dir := tok[:strings.LastIndexByte(tok, '/')]
		// Prefer the deepest (most specific) directory among the fact's paths.
		if best == "" || strings.Count(dir, "/") > strings.Count(best, "/") {
			best = dir
		}
	}
	return best
}

// looksLikeSourcePath reports whether a locus token is a real source-file path
// (`some/dir/name.ext` with a short lowercase extension), distinguishing it from
// a slash-bearing prose fragment.
func looksLikeSourcePath(tok string) bool {
	// Reject absolute/relative/home-anchored and drive-lettered paths — a tiered
	// home should be a repo-relative source directory, not "..", "~/…", or "d:/…".
	if strings.HasPrefix(tok, "/") || strings.HasPrefix(tok, "..") || strings.HasPrefix(tok, "~") || strings.ContainsAny(tok, ": ") {
		return false
	}
	i := strings.LastIndexByte(tok, '/')
	if i <= 0 {
		return false
	}
	base := tok[i+1:]
	dot := strings.LastIndexByte(base, '.')
	if dot <= 0 || dot == len(base)-1 {
		return false
	}
	ext := base[dot+1:]
	if len(ext) < 1 || len(ext) > 5 {
		return false
	}
	for _, r := range ext {
		if r < 'a' || r > 'z' {
			return false
		}
	}
	return true
}

// buildFactOutlineTree builds the deterministic outline structure (no summaries)
// from a branch's facts: every active fact is homed at its tier, ancestor tiers
// are materialized, children are wired, and per-node by-kind counts recorded.
// Fingerprints are computed bottom-up so any leaf or structural change beneath a
// node changes that node's fingerprint (driving incremental re-summarization).
func buildFactOutlineTree(branch string, facts []factRecord, now time.Time) factOutline {
	nodes := map[string]*factOutlineNode{}
	ensure := func(key string) *factOutlineNode {
		if n, ok := nodes[key]; ok {
			return n
		}
		n := &factOutlineNode{Key: key, Label: outlineLabel(key), Counts: map[string]int{}}
		nodes[key] = n
		return n
	}
	ensure("") // root always exists
	for _, f := range facts {
		if f.Status != factStatusActive {
			continue
		}
		key := factHomeKey(f)
		ensure(key)
		for anc := key; anc != ""; anc = parentKey(anc) {
			ensure(parentKey(anc))
		}
		n := nodes[key]
		n.LeafFactIDs = append(n.LeafFactIDs, f.ID)
		n.Counts[factKindOrInferred(f)]++
	}
	// Wire children and sort everything for determinism.
	for key := range nodes {
		if key == "" {
			continue
		}
		p := nodes[parentKey(key)]
		p.Children = append(p.Children, key)
	}
	for _, n := range nodes {
		sort.Strings(n.Children)
		sort.Strings(n.LeafFactIDs)
		if len(n.Counts) == 0 {
			n.Counts = nil
		}
	}
	// Bottom-up fingerprints: a node hashes its leaf ids + each child's
	// fingerprint, so a change anywhere in the subtree propagates to the root.
	var fingerprint func(key string) string
	fingerprint = func(key string) string {
		n := nodes[key]
		h := sha256.New()
		for _, id := range n.LeafFactIDs {
			h.Write([]byte(id))
			h.Write([]byte{0})
		}
		for _, c := range n.Children {
			h.Write([]byte(c))
			h.Write([]byte{1})
			h.Write([]byte(fingerprint(c)))
		}
package cli

import (
	"fmt"
	"sort"
	"strings"

	"github.com/spf13/cobra"
)

// factTreeNode groups a branch's facts into a navigable hierarchy keyed by
// taxonomy path. category nodes hold subcategory.type leaves; each leaf holds
// the facts at that exact path. Counts roll up so a caller can read the top of
// the tree (categories) and drill into only the subtree it needs — progressive
// disclosure that keeps both an agent's token load and a human's reading bounded.
type factTreeNode struct {
	Label    string          `json:"label"`
	Count    int             `json:"count"`
	Children []*factTreeNode `json:"children,omitempty"`
	Facts    []factRecord    `json:"facts,omitempty"`
}

// buildFactTree organizes active facts into a two-level outline: top-level
// category (the first path segment) → full taxonomy path (the leaf). Only active
// facts are included unless includeAll. A fact under two paths appears under
// both. Nodes and leaves are ordered by descending count, then label, so the
// densest, most load-bearing areas surface first.
func buildFactTree(facts []factRecord, includeAll bool) *factTreeNode {
	type leaf struct {
		records []factRecord
	}
	cats := map[string]map[string]*leaf{}
	for _, f := range facts {
		if !includeAll && f.Status != factStatusActive {
			continue
		}
		for _, path := range f.Paths {
			cat := factTopLevel(path)
			if cats[cat] == nil {
				cats[cat] = map[string]*leaf{}
			}
			if cats[cat][path] == nil {
				cats[cat][path] = &leaf{}
			}
			cats[cat][path].records = append(cats[cat][path].records, f)
		}
	}

	root := &factTreeNode{Label: "facts"}
	for cat, leaves := range cats {
		catNode := &factTreeNode{Label: cat}
		for path, l := range leaves {
			records := append([]factRecord(nil), l.records...)
			sortFactsByImportance(records)
			catNode.Children = append(catNode.Children, &factTreeNode{Label: path, Count: len(records), Facts: records})
			catNode.Count += len(records)
		}
		sortTreeChildren(catNode.Children)
		root.Children = append(root.Children, catNode)
		root.Count += catNode.Count
	}
	sortTreeChildren(root.Children)
	return root
}

// distinctFactCount returns the number of distinct facts under a tree. Node
// Count fields total path occurrences (so a path-dense area reads as dense),
// which double-counts a fact carried under two paths; the "N facts" header must
// use this distinct count instead.
func distinctFactCount(root *factTreeNode) int {
	seen := map[string]struct{}{}
	for _, cat := range root.Children {
		for _, leaf := range cat.Children {
			for _, f := range leaf.Facts {
				seen[f.ID] = struct{}{}
			}
		}
	}
	return len(seen)
}

// sortFactsByImportance orders facts within a leaf by a crude importance proxy:
// more provenance anchors first (corroborated by more sessions), then most
// recently updated. This surfaces the load-bearing facts as a leaf's
// representatives.
func sortFactsByImportance(records []factRecord) {
	sort.SliceStable(records, func(i, j int) bool {
		if len(records[i].Provenance) != len(records[j].Provenance) {
			return len(records[i].Provenance) > len(records[j].Provenance)
		}
		return records[i].UpdatedAt.After(records[j].UpdatedAt)
	})
}

func sortTreeChildren(children []*factTreeNode) {
	sort.SliceStable(children, func(i, j int) bool {
		if children[i].Count != children[j].Count {
			return children[i].Count > children[j].Count
		}
		return children[i].Label < children[j].Label
	})
}

// filterTreeByPath prunes the tree to the subtree under the given path prefix
// (a category like "constraints" or a full path). Returns nil if nothing
// matches.
func filterTreeByPath(root *factTreeNode, prefix string) *factTreeNode {
	prefix = strings.TrimSpace(prefix)
	if prefix == "" {
		return root
	}
	out := &factTreeNode{Label: root.Label}
	for _, cat := range root.Children {
		if cat.Label == prefix {
			out.Children = append(out.Children, cat)
			out.Count += cat.Count
			continue
		}
		kept := &factTreeNode{Label: cat.Label}
		for _, leaf := range cat.Children {
			if leaf.Label == prefix || strings.HasPrefix(leaf.Label, prefix+".") {
				kept.Children = append(kept.Children, leaf)
				kept.Count += leaf.Count
			}
		}
		if len(kept.Children) > 0 {
			out.Children = append(out.Children, kept)
			out.Count += kept.Count
		}
	}
	if len(out.Children) == 0 {
		return nil
	}
	return out
}

// renderFactTree writes the outline. depth 1 prints categories only; depth 2
// adds the path leaves; depth >= 3 adds up to `leaves` sample facts per leaf
// with a "+N more" pointer so the rest is reachable via recall or a deeper
// drill, never silently hidden.
func renderFactTree(cmd *cobra.Command, root *factTreeNode, depth, leaves int) {
	for _, cat := range root.Children {
		fmt.Fprintf(cmd.OutOrStdout(), "%s (%d)\n", cat.Label, cat.Count)
		if depth < 2 {
			continue
		}
		for _, leaf := range cat.Children {
			fmt.Fprintf(cmd.OutOrStdout(), "  %s (%d)\n", leaf.Label, leaf.Count)
			if depth < 3 {
				continue
			}
			shown := leaf.Facts
			if len(shown) > leaves {
				shown = shown[:leaves]
			}
			for _, f := range shown {
				fmt.Fprintf(cmd.OutOrStdout(), "    - %s\n", truncateString(f.Text, 140))
			}
			if rest := leaf.Count - len(shown); rest > 0 {
				fmt.Fprintf(cmd.OutOrStdout(), "    (+%d more — drill with --path %s)\n", rest, leaf.Label)

