		}
		for _, c := range n.Children {
			h.Write([]byte(c))
			h.Write([]byte{1})
			h.Write([]byte(fingerprint(c)))
		}
		sum := hex.EncodeToString(h.Sum(nil)[:12])
		n.Fingerprint = sum
		return sum
	}
