}"},{"rank":2,"score":49.8632,"file_path":"internal/cli/facts_locus.go","start_line":134,"end_line":139,"focus_line":134,"snippet_start_line":134,"snippet_end_line":139,"symbol_start_line":134,"symbol_end_line":139,"language":"Go","kind":"function","symbol_id":"gh/entireio/entire-brain:Go:internal/cli/facts_locus.go:function:factKindOrInferred","symbol_name":"factKindOrInferred","qualified_name":"factKindOrInferred","signature":"func factKindOrInferred(f factRecord) string","signals":["graph:calls","graph:outgoing","graph:callers"],"snippet":"func factKindOrInferred(f factRecord) string {
