{"format_version":1,"query":"runSemanticIngestTraces semanticRuntimeTraceFacts readRuntimeTraces callers and failure paths","repo_root":"/Users/thomi/.codex/worktrees/04638663-839c-4e0a-9303-5b0278f98cd0/entire-brain","commit":"88519f77572ec1ad2b7cb93ffa81abdb1f303262","tree":"1e3eef2478afa64f2d64d45fb4b3a1b4c3daacd1","profile":"full","results":[{"rank":1,"score":143.91,"file_path":"internal/cli/semantic_graph.go","start_line":970,"end_line":1092,"focus_line":970,"snippet_start_line":970,"snippet_end_line":1092,"symbol_start_line":970,"symbol_end_line":1092,"language":"Go","kind":"function","symbol_id":"gh/entireio/entire-brain:Go:internal/cli/semantic_graph.go:function:runSemanticIngestTraces","symbol_name":"runSemanticIngestTraces","qualified_name":"runSemanticIngestTraces","signature":"func runSemanticIngestTraces(cmd *cobra.Command, opts Options, ingestOpts semanticTraceIngestOptions, path string) error","signals":["body","exact-symbol","symbol-name","signature","exact-code-token","graph:callers","complete-symbol"],"snippet":"func runSemanticIngestTraces(cmd *cobra.Command, opts Options, ingestOpts semanticTraceIngestOptions, path string) error {
	env, err := loadSemanticEnv(cmd, opts)
	if err != nil {
		return err
	}
	// Read and parse the caller-supplied trace file BEFORE taking the index lock.
	// The path is untrusted (the brain_ingest_traces MCP tool accepts an arbitrary
	// path), so any time spent on it must not be time the index lock is held —
	// otherwise one hostile path denies the lock to every other caller on this
	// brain. This does not weaken the reload invariant below: traces are input
	// data, not brain state, and nothing staged or published is derived from the
	// manifest read above.
	traces, err := readRuntimeTraces(path)
	if err != nil {
		return err
	}
	unlock, err := acquireSemanticIndexLock(env.BrainDir)
	if err != nil {
		return err
	}
	defer unlock()
	// Reload after taking the index lock so an index publication that completed
	// while we waited cannot be replaced by a trace generation cloned from stale
	// manifest state.
	env, err = loadSemanticEnv(cmd, opts)
	if err != nil {
		return err
	}
	report := semanticTraceIngestReport{
		ImportedAt: opts.Now().UTC(),
		Path:       filepath.ToSlash(path),
		Total:      len(traces),
	}
	staging, generationRel, generationID, err := stageSemanticTraceGeneration(env, report, traces)
	if err != nil {
		return err
	}
	published := false
	defer func() {
		if !published {
			_ = os.RemoveAll(staging)
		}
	}()
	db, err := sql.Open(sqliteDriverName, filepath.Join(staging, semanticSQLiteName))
	if err != nil {
		return err
	}
	if err := ensureSemanticRuntimeTraceTable(db); err != nil {
		_ = db.Close()
		return err
	}
	matched := 0
	traceMatches := make([]bool, len(traces))
	for i, trace := range traces {
		ok, err := runtimeTraceMatchesStaticEdge(db, trace)
		if err != nil {
			_ = db.Close()
			return err
		}
		if ok {
			matched++
		}
		traceMatches[i] = ok
	}
	report.Matched = matched
	report.Unmatched = len(traces) - matched
	rel, err := writeRuntimeTraceImport(env.BrainDir, report, traces)
	if err != nil {
		_ = db.Close()
		return err
	}
	report.Path = rel
	if err := insertRuntimeTraceFacts(db, report, traces, traceMatches); err != nil {
		_ = db.Close()
		return err
	}
	if _, err := db.Exec(`INSERT OR REPLACE INTO meta(key, value) VALUES ('generation_id', ?)`, generationID); err != nil {
		_ = db.Close()
		return err
	}
	if _, err := db.Exec(`PRAGMA wal_checkpoint(TRUNCATE)`); err != nil {
		_ = db.Close()
		return err
	}
	if err := db.Close(); err != nil {
		return err
	}
	if err := rewriteSemanticTraceGenerationMetrics(staging, generationID, report.ImportedAt); err != nil {
		return err
	}
	finalDir := filepath.Join(env.BrainDir, filepath.FromSlash(generationRel))
	if err := rejectExistingSymlinkPathComponents(env.BrainDir, filepath.FromSlash(generationRel)); err != nil {
		return err
	}
	if _, err := os.Lstat(finalDir); err == nil {
		return fmt.Errorf("semantic trace generation target already exists: %s", finalDir)
	} else if !os.IsNotExist(err) {
		return err
	}
	if err := os.Rename(staging, finalDir); err != nil {
		return err
	}
	published = true
	updated := *env.Source
	updated.GeneratedAt = report.ImportedAt
	rewriteSemanticGenerationRefs(&updated, generationRel)
	if err := writeBrainSemanticSource(env.BrainDir, env.RepoKey, &updated); err != nil {
		return err
	}
	snapshotRel, err := validateSemanticSnapshotPath(updated.SnapshotPath)
	if err != nil {
		return err
	}
	snapshotID := filepath.Base(filepath.Dir(snapshotRel))
	if err := writeSemanticSnapshotManifest(env.BrainDir, snapshotID, &updated); err != nil {
		return err
	}
	if ingestOpts.json {
		return writeJSON(cmd, report)
	}
	fmt.Fprintf(cmd.OutOrStdout(), "ingested runtime traces: %d\nmatched_static_edges: %d\nartifact: %s\n", report.Total, report.Matched, report.Path)
	return nil
}"},{"rank":2,"score":132.0835,"file_path":"internal/cli/semantic.go","start_line":1124,"end_line":1137,"focus_line":1124,"snippet_start_line":1124,"snippet_end_line":1137,"symbol_start_line":1124,"symbol_end_line":1137,"language":"Go","kind":"function","symbol_id":"gh/entireio/entire-brain:Go:internal/cli/semantic.go:function:acquireSemanticIndexLock","symbol_name":"acquireSemanticIndexLock","qualified_name":"acquireSemanticIndexLock","signature":"func acquireSemanticIndexLock(brainDir string) (func(), error)","signals":["graph:calls","graph:outgoing","graph:callers","complete-symbol"],"snippet":"func acquireSemanticIndexLock(brainDir string) (func(), error) {
