func runSemanticIngestTraces(cmd *cobra.Command, opts Options, ingestOpts semanticTraceIngestOptions, path string) error {
	env, err := loadSemanticEnv(cmd, opts)
	if err != nil {
		return err
	}
	// Read and parse the caller-supplied trace file BEFORE taking the index lock.
	// The path is untrusted (the brain_ingest_traces MCP tool accepts an arbitrary
	// path), so any time spent on it must not be time the index lock is held —
	// otherwise one hostile path denies the lock to every other caller on this
	// brain. This does not weaken the reload invariant below: traces are input
	// data, not brain state, and nothing staged or published is derived from the
	// manifest read above.
	traces, err := readRuntimeTraces(path)
	if err != nil {
		return err
	}
	unlock, err := acquireSemanticIndexLock(env.BrainDir)
	if err != nil {
		return err
	}
	defer unlock()
	// Reload after taking the index lock so an index publication that completed
	// while we waited cannot be replaced by a trace generation cloned from stale
	// manifest state.
	env, err = loadSemanticEnv(cmd, opts)
	if err != nil {
		return err
	}
	report := semanticTraceIngestReport{
		ImportedAt: opts.Now().UTC(),
		Path:       filepath.ToSlash(path),
		Total:      len(traces),
	}
	staging, generationRel, generationID, err := stageSemanticTraceGeneration(env, report, traces)
	if err != nil {
		return err
	}
	published := false
	defer func() {
		if !published {
			_ = os.RemoveAll(staging)
		}
	}()
	db, err := sql.Open(sqliteDriverName, filepath.Join(staging, semanticSQLiteName))
	if err != nil {
		return err
	}
	if err := ensureSemanticRuntimeTraceTable(db); err != nil {
		_ = db.Close()
		return err
	}
	matched := 0
	traceMatches := make([]bool, len(traces))
	for i, trace := range traces {
		ok, err := runtimeTraceMatchesStaticEdge(db, trace)
		if err != nil {
			_ = db.Close()
			return err
		}
		if ok {
			matched++
		}
		traceMatches[i] = ok
	}
	report.Matched = matched
	report.Unmatched = len(traces) - matched
	rel, err := writeRuntimeTraceImport(env.BrainDir, report, traces)
	if err != nil {
		_ = db.Close()
		return err
	}
	report.Path = rel
	if err := insertRuntimeTraceFacts(db, report, traces, traceMatches); err != nil {
		_ = db.Close()
		return err
	}
	if _, err := db.Exec(`INSERT OR REPLACE INTO meta(key, value) VALUES ('generation_id', ?)`, generationID); err != nil {
		_ = db.Close()
		return err
	}
	if _, err := db.Exec(`PRAGMA wal_checkpoint(TRUNCATE)`); err != nil {
		_ = db.Close()
		return err
	}
	if err := db.Close(); err != nil {
		return err
	}
	if err := rewriteSemanticTraceGenerationMetrics(staging, generationID, report.ImportedAt); err != nil {
		return err
	}
	finalDir := filepath.Join(env.BrainDir, filepath.FromSlash(generationRel))
	if err := rejectExistingSymlinkPathComponents(env.BrainDir, filepath.FromSlash(generationRel)); err != nil {
		return err
	}
	if _, err := os.Lstat(finalDir); err == nil {
		return fmt.Errorf("semantic trace generation target already exists: %s", finalDir)
	} else if !os.IsNotExist(err) {
		return err
	}
	if err := os.Rename(staging, finalDir); err != nil {
		return err
	}
	published = true
	updated := *env.Source
	updated.GeneratedAt = report.ImportedAt
	rewriteSemanticGenerationRefs(&updated, generationRel)
	if err := writeBrainSemanticSource(env.BrainDir, env.RepoKey, &updated); err != nil {
		return err
	}
	snapshotRel, err := validateSemanticSnapshotPath(updated.SnapshotPath)
	if err != nil {
		return err
	}
	snapshotID := filepath.Base(filepath.Dir(snapshotRel))
	if err := writeSemanticSnapshotManifest(env.BrainDir, snapshotID, &updated); err != nil {
		return err
	}
	if ingestOpts.json {
		return writeJSON(cmd, report)
	}
	fmt.Fprintf(cmd.OutOrStdout(), "ingested runtime traces: %d\nmatched_static_edges: %d\nartifact: %s\n", report.Total, report.Matched, report.Path)
	return nil
}

func stageSemanticTraceGeneration(env semanticEnv, report semanticTraceIngestReport, traces []semanticRuntimeTrace) (string, string, string, error) {
	generationRel, err := validateSemanticGenerationPath(env.Source.GenerationPath)
	}
	fullPath := filepath.Join(brainDir, snapshotPath)
	symbols, err := findSemanticSymbols(fullPath, query, limit, offset)
	if err != nil {
		return nil, nil, nil, err
	}
	relations, err := findSemanticRelationsForSymbols(fullPath, symbols, limit*4)
	if err != nil {
		return nil, nil, nil, err
	}
	var neighbors []semanticRecord
	if ids := neighborCandidateIDs(symbols, relations); len(ids) > 0 {
		symbolsByID, err := loadSemanticSymbolsByIDsSnapshot(fullPath, ids)
		if err != nil {
			return nil, nil, nil, err
		}
		neighbors = resolveContextNeighbors(symbols, relations, symbolsByID, limit)
	}
	return symbols, relations, neighbors, nil
}

func semanticRuntimeTraceFacts(brainDir string, source *semanticSourceManifest, query string, limit int) ([]semanticRecord, error) {
	if limit <= 0 {
		return []semanticRecord{}, nil
	}
	if source.StorePath == "" {
		return []semanticRecord{}, nil
	}
	storePath, err := validateSemanticDeclaredStore(brainDir, source)
	if err != nil {
		return nil, err
	}
	db, err := sql.Open(sqliteDriverName, sqliteReadOnlyDSN(storePath))
	if err != nil {
		return nil, err
	}
	defer db.Close()
	if err := ensureSemanticRuntimeTraceTable(db); err != nil {
		return nil, err
	}
	rows, err := db.Query(`
SELECT rt.from_id,
       COALESCE(to_sym.id, rt.to_id) AS to_id,
       rt.observed_type,
       rt.matched_static_edge,
       rt.source_path,
       COALESCE(from_sym.file_path, '') AS from_file,
       COALESCE(to_sym.file_path, '') AS to_file,
       COALESCE(from_sym.name, '') AS from_name,
       COALESCE(from_sym.qualified_name, '') AS from_qualified,
       COALESCE(to_sym.name, '') AS to_name,
       COALESCE(to_sym.qualified_name, '') AS to_qualified
FROM runtime_traces rt
LEFT JOIN symbols from_sym ON from_sym.id = rt.from_id OR from_sym.name = rt.from_id OR from_sym.qualified_name = rt.from_id
LEFT JOIN symbols to_sym ON to_sym.id = rt.to_id OR to_sym.name = rt.to_id OR to_sym.qualified_name = rt.to_id
ORDER BY rt.imported_at DESC, rt.id DESC
LIMIT ?`, limit*8)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	terms := brainBriefFileMatchTerms(query)
	var records []semanticRecord
	for rows.Next() {
		var record semanticRecord
		var observedType, sourcePath, fromFile, toFile, fromName, fromQualified, toName, toQualified string
		var matched int
		if err := rows.Scan(&record.FromID, &record.ToID, &observedType, &matched, &sourcePath, &fromFile, &toFile, &fromName, &fromQualified, &toName, &toQualified); err != nil {
			return nil, err
		}
		record.RecordType = "runtime_trace"
		record.Type = "RUNTIME_TRACE"
		record.Confidence = 1
		record.FilePath = semanticFirstNonEmpty(fromFile, toFile)
		record.Path = record.FilePath
		record.Reason = strings.TrimSpace("runtime trace observed " + observedType)
		if record.Reason == "runtime trace observed" {
			record.Reason = "runtime trace observed edge"
		}
		if matched == 0 {
			record.Confidence = 0.5
			record.WarningCodes = []string{"UNMATCHED_STATIC_EDGE"}
		} else {
			record.WarningCodes = []string{}
		}
		record.Evidence = []semanticEvidence{{Kind: "runtime_trace_import", FilePath: sourcePath, Detail: observedType}}
		record.Score = runtimeTraceTaskScore(record, terms, fromFile, toFile, fromName, fromQualified, toName, toQualified, observedType)
		records = append(records, record)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	sort.Slice(records, func(i, j int) bool {
		if records[i].Score == records[j].Score {
			if records[i].Confidence == records[j].Confidence {
				if records[i].FilePath == records[j].FilePath {
					if records[i].FromID == records[j].FromID {
						return records[i].ToID < records[j].ToID
					}
					return records[i].FromID < records[j].FromID
				}
				return records[i].FilePath < records[j].FilePath
			}
			return records[i].Confidence > records[j].Confidence
		}
		return records[i].Score > records[j].Score
	})
	if len(records) > limit {
		records = records[:limit]
	}
	return nonNil(records), nil
}

func runtimeTraceTaskScore(record semanticRecord, terms []string, fields ...string) int {
	haystack := strings.ToLower(strings.Join(append([]string{record.FromID, record.ToID, record.FilePath, record.Reason}, fields...), " "))
	score := 0
	for _, term := range terms {
		if term != "" && strings.Contains(haystack, strings.ToLower(term)) {
			score += 3
		}
	}
	if record.Confidence >= 1 {
		score++
	}
	return score
}
