	haystack := strings.ToLower(strings.Join(append([]string{record.FromID, record.ToID, record.FilePath, record.Reason}, fields...), " "))
	score := 0
	for _, term := range terms {
		if term != "" && strings.Contains(haystack, strings.ToLower(term)) {
