		if statErr != nil && !os.IsNotExist(statErr) {
			return "", fmt.Errorf("stat output directory: %w", statErr)
		}
	} else {
		abs, err = validateExportDirAvailable(path)
		if err != nil {
			return "", err
		}
func repoStoragePaths(ctx context.Context, runner CommandRunner, env EntireEnv, repoDir string) (repoStorage, error) {
	set, err := resolveRepoStorageSet(ctx, runner, env, repoDir)
	if err != nil {
		return repoStorage{}, err
	}
	// Refuse to guess whenever more than one spelling holds state: picking
	// either would hide the other repository history. The refusal names the
	// command that resolves it -- see localRepoIdentityConflictError.
	if err := set.conflictError(); err != nil {
		return repoStorage{}, err
	}
	// Otherwise preserve the exact established key in place. This is atomic
	// because no files move, and it avoids a cross-root brain/head migration
	// that could only be partially committed if the process or filesystem
	// fails.
	return set.Active(), nil
}

func repoStorageForKey(dirs pluginDirs, key string) repoStorage {
	return repoStorage{
		Key:      key,
		BrainDir: filepath.Join(dirs.Data, repoStoreDirName, filepath.FromSlash(key)),
		HeadPath: filepath.Join(dirs.State, repoStoreDirName, filepath.FromSlash(key), brainHeadFileName),
	}
}

func repoStorageContainsState(storage repoStorage) (bool, error) {
	for _, path := range []string{storage.BrainDir, storage.HeadPath} {
		_, err := os.Lstat(path)
		switch {
		case err == nil:
			return true, nil
		case errors.Is(err, os.ErrNotExist):
			continue
		default:
			return false, fmt.Errorf("inspect repo identity state %s: %w", path, err)
		}
	}
	return false, nil
}

// rejectReservedRepoKeySegment refuses a repo key whose first segment is
// reserved in the repo keyspace.
//
// "workspaces" is reserved: older builds stored workspace manifests at
// repos/workspaces/<name> (since relocated to a sibling of repos/), and a host
// slug or hand-edited DomainSlugs entry claiming the segment would collide with
// any legacy data still awaiting migration.
//
// This lives in one function because it is a property of the KEY, not of any one
// consumer of it. It used to be inline in brainDirForKey only, which left the two
// places that build a store path without that helper — `brain path`, and
// headPathForKey — accepting a key every other command refuses.
func rejectReservedRepoKeySegment(key string) error {
	if first, _, _ := strings.Cut(key, "/"); first == workspaceDirName {
		return fmt.Errorf("repo key uses the reserved %q segment: %s", workspaceDirName, key)
	}
	return nil
}

func brainDirForKey(env EntireEnv, key string) (string, error) {
	if err := rejectReservedRepoKeySegment(key); err != nil {
		return "", err
	}
	dirs, err := resolvePluginDirs(env)
	if err != nil {
		return "", err
	}
	brainRoot := filepath.Join(dirs.Data, repoStoreDirName)
	if err := rejectBrainRootPathSymlinks(brainRoot, filepath.FromSlash(key)); err != nil {
		return "", err
	}
	return filepath.Join(brainRoot, filepath.FromSlash(key)), nil
}

func semanticStaleReport(ctx context.Context, opts Options, target string) (staleReport, error) {
	repoDir, local, err := resolveLocalTargetRepoDir(ctx, opts.Runner, target)
	if err != nil {
		return staleReport{}, err
	}
	if !local {
		return staleReport{}, fmt.Errorf("stale requires a local repository path: %s", target)
	}
	storage, err := repoStoragePaths(ctx, opts.Runner, opts.Env, repoDir)
	if err != nil {
		return staleReport{}, err
	}
	manifest, err := loadBrainManifest(storage.BrainDir)
	if err != nil {
		return staleReport{}, err
	}
	axes := map[string]staleAxis{}
	if manifest.Sources == nil || manifest.Sources.Semantic == nil {
		axes["semantic"] = staleAxis{State: "missing", Detail: "no semantic source in manifest"}
		return staleReport{Severity: "unsafe", Axes: axes}, nil
	}
	source := manifest.Sources.Semantic
	if source.SnapshotPath == "" {
		axes["snapshot"] = staleAxis{State: "unsafe", Detail: "semantic snapshot_path is missing"}
	} else if _, err := validateSemanticSnapshotPath(source.SnapshotPath); err != nil {
		axes["snapshot"] = staleAxis{State: "unsafe", Detail: err.Error()}
	} else if err := rejectSymlinkPathComponents(storage.BrainDir, filepath.FromSlash(source.SnapshotPath)); err != nil {
		axes["snapshot"] = staleAxis{State: "unsafe", Detail: err.Error()}
	} else {
		snapshotPath := filepath.Join(storage.BrainDir, filepath.FromSlash(source.SnapshotPath))
		snapshotHeader, snapshotCounts, snapshotErr := readSemanticSnapshotSummary(snapshotPath, storage.Key)
		if snapshotErr != nil {
			axes["snapshot"] = staleAxis{State: "unsafe", Detail: snapshotErr.Error()}
		} else if err := validateSemanticSourceMatchesSnapshot(source, snapshotHeader, snapshotCounts); err != nil {
			axes["snapshot"] = staleAxis{State: "unsafe", Detail: err.Error()}
		} else {
			axes["snapshot"] = staleAxis{State: "ok", Detail: source.SnapshotPath}
		}
	}
	if source.StorePath != "" {
		if source.GenerationPath == "" {
			axes["store"] = staleAxis{State: "unsafe", Detail: "semantic generation_path is missing"}
		} else if generationPath, err := validateSemanticGenerationPath(source.GenerationPath); err != nil {
			axes["store"] = staleAxis{State: "unsafe", Detail: err.Error()}
		} else if storePath, err := validateSemanticGenerationFilePath(source.StorePath, generationPath, semanticSQLiteName); err != nil {
			axes["store"] = staleAxis{State: "unsafe", Detail: err.Error()}
		} else if err := rejectSymlinkPathComponents(storage.BrainDir, storePath); err != nil {
			axes["store"] = staleAxis{State: "unsafe", Detail: err.Error()}
		} else if err := validateSemanticSQLiteStore(filepath.Join(storage.BrainDir, storePath), source.Symbols, source.Relations); err != nil {
			axes["store"] = staleAxis{State: "unsafe", Detail: err.Error()}
		} else {
			axes["store"] = staleAxis{State: "ok", Detail: source.StorePath}
		}
	}
	head, headErr := gitScalar(ctx, opts.Runner, repoDir, "rev-parse", "HEAD")
	branch, branchErr := gitScalar(ctx, opts.Runner, repoDir, "branch", "--show-current")
	dirty, dirtyErr := worktreeDirty(ctx, opts.Runner, repoDir)
	currentWorktreeHash := ""
	var currentWorktreeHashErr error
	if dirty && source.WorktreeHash != "" {
		currentWorktreeHash, currentWorktreeHashErr = worktreeFingerprint(ctx, opts.Runner, repoDir)
	}
	if headErr != nil {
		axes["head"] = staleAxis{State: "unsafe", Detail: "HEAD unavailable: " + headErr.Error(), Indexed: source.Commit}
	} else if source.Commit == head {
		axes["head"] = staleAxis{State: "ok", Current: head, Indexed: source.Commit}
	} else {
		axes["head"] = staleAxis{State: "stale", Current: head, Indexed: source.Commit}
	}
	if branchErr != nil {
		axes["branch_tip"] = staleAxis{State: "unsafe", Detail: "branch unavailable: " + branchErr.Error(), Indexed: source.Branch}
	} else if source.Branch == "" || source.Branch == branch {
		axes["branch_tip"] = staleAxis{State: "ok", Current: branch, Indexed: source.Branch}
	} else {
		axes["branch_tip"] = staleAxis{State: "stale", Current: branch, Indexed: source.Branch}
	}

